+++ b/src/io/sales-import.js
@@ -0,0 +1,105 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Already-imported tickets are skipped. The whole file is checked and staged
+// first; one invalid row or stock shortfall and nothing is imported.
+import { isDate } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const ISO_INSTANT = /^(\d{4}-\d{2}-\d{2})[Tt](\d{2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?([Zz]|[+-]\d{2}:\d{2})$/;
+
+function parseInstant(value) {
+  const m = ISO_INSTANT.exec(value);
+  if (!m || !isDate(m[1])) return null;
+  const [, , hh, mm, ss = "00", tz] = m;
+  if (Number(hh) > 23 || Number(mm) > 59 || Number(ss) > 59) return null;
+  if (tz !== "Z" && tz !== "z") {
+    const [th, tm] = tz.slice(1).split(":").map(Number);
+    if (th > 23 || tm > 59) return null;
+  }
+  const ms = Date.parse(value);
+  return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
+}
+
+/** Imports sales from CSV; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const parsed = parseCsv(text);
+  if (parsed.length === 0) return { tickets: 0, dishes: 0 };
+  const [head, ...dataRows] = parsed;
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const rows = dataRows.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] ?? "").trim()])));
+
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    const soldAt = parseInstant(r.soldAt);
+    if (!soldAt) throw new AppError("bad_request", { reason: `${where}: invalid soldAt` });
+    const dishId = Number(r.dishId);
+    if (!r.dishId || !Number.isInteger(dishId) || dishId < 1) {
+      throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    }
+    let dish;
+    try {
+      dish = getDish(store, dishId);
+    } catch (err) {
+      if (err instanceof AppError && err.code === "not_found") {
+        throw new AppError("bad_request", { reason: `${where}: unknown dish ${dishId}` });
+      }
+      throw err;
+    }
+    getRecipe(store, dish.recipeId);
+    const qty = Number(r.qty);
+    if (!r.qty || !Number.isInteger(qty) || qty < 1) {
+      throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    }
+    return { where, ticket: r.ticket, soldAt, dishId, recipeId: dish.recipeId, qty };
+  });
+
+  const existingTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const stagedData = structuredClone(store.data);
+  stagedData.sales ??= [];
+  const stage = {
+    data: stagedData,
+    nextId(kind) {
+      stagedData.seq[kind] = (stagedData.seq[kind] ?? 0) + 1;
+      return stagedData.seq[kind];
+    },
+  };
+
+  const importedTickets = new Set();
+  let dishes = 0;
+
+  for (const row of clean) {
+    if (existingTickets.has(row.ticket)) continue;
+    const recipe = getRecipe(stage, row.recipeId);
+    for (const n of scaled(recipe, row.qty)) {
+      if (n.qty <= 0) continue;
+      try {
+        consume(stage, n.itemId, n.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+      } catch (err) {
+        if (err instanceof AppError && err.code === "not_enough_stock") {
+          throw new AppError("row_not_enough_stock", { where: row.where, ...err.params });
+        }
+        throw err;
+      }
+    }
+    stagedData.sales.push({
+      id: stage.nextId("sale"),
+      ticket: row.ticket,
+      soldAt: row.soldAt,
+      dishId: row.dishId,
+      qty: row.qty,
+    });
+    importedTickets.add(row.ticket);
+    dishes += row.qty;
+  }
+
+  Object.assign(store.data, stagedData);
+  return { tickets: importedTickets.size, dishes };
+}
